import type { Guest } from "../types";
import { shq } from "../types";

/**
 * Config-file strategy: read-modify-write ONE file on the guest with a backup,
 * verification and rollback.
 *
 *   read -> patch(old) -> validate(new) -> (identical? stop: idempotent no-op)
 *   -> backup (path.nxbak) -> write -> read back + validate -> done
 *
 * The patch function is one of kit/json-patch, ini-patch, kv-patch (or your own);
 * it must preserve keys it was not asked to change. Nothing is written when the
 * file is missing or does not parse. The caller decides what happens after
 * (restart etc.) and can still call `restore()` if a LATER step fails.
 */
export type FilePatchResult =
  | { status: "missing" }
  | { status: "invalid"; reason: string }
  | { status: "unchanged" }
  /** Written and verified. `restore` puts the previous content back; `commit` drops the backup. */
  | { status: "changed"; restore(): Promise<void>; commit(): Promise<void> }
  /** The write did not verify; the previous content was restored. */
  | { status: "failed"; reason: string };

export async function patchRemoteFile(
  guest: Guest,
  opts: {
    path: string;
    patch(old: string): string;
    /** Returns an error string if the content is not acceptable (checked before AND after writing). */
    validate?(content: string): string | null;
  },
): Promise<FilePatchResult> {
  const { path } = opts;
  const old = await guest.readFile(path);
  if (old === null) return { status: "missing" };

  let next: string;
  try {
    next = opts.patch(old);
  } catch {
    // Deliberately not echoing the parser's message: it can quote file content.
    return { status: "invalid", reason: `${path} could not be parsed, so it was left untouched.` };
  }
  const bad = opts.validate?.(next);
  if (bad) return { status: "invalid", reason: `${bad} ${path} was left untouched.` };
  if (next === old) return { status: "unchanged" };

  const backup = await guest.exec(`cp -p ${shq(path)} ${shq(path + ".nxbak")}`);
  if (backup.code !== 0) return { status: "failed", reason: `Could not back up ${path} first, so nothing was changed.` };

  const restore = async () => {
    await guest.writeFile(path, old);
    await guest.exec(`rm -f ${shq(path + ".nxbak")}`);
  };

  try {
    await guest.writeFile(path, next);
    const back = await guest.readFile(path);
    const backBad = back === null ? "missing after write" : back !== next ? "differs from what was written" : opts.validate?.(back);
    if (backBad) {
      await restore();
      return { status: "failed", reason: `${path} did not verify after writing (${backBad}); the previous version was restored.` };
    }
  } catch (e) {
    await restore().catch(() => undefined);
    return { status: "failed", reason: `Writing ${path} failed (${(e as Error).message.slice(0, 120)}); the previous version was restored.` };
  }
  return {
    status: "changed",
    restore,
    commit: async () => void (await guest.exec(`rm -f ${shq(path + ".nxbak")}`)),
  };
}
import type { Guest } from "../types";
import { shq } from "../types";

/**
 * Env-recreate strategy: rebuild a game container with changed environment
 * (and/or launch args) while keeping every volume. Generalises
 * worker/zomboid-admin.ts (same safety shape): the OLD container is kept,
 * renamed `<name>-old`, until the new one is verified; any failure puts it back
 * and restarts it if the game was running. A server the customer had stopped is
 * rebuilt but NOT started.
 *
 *   inspect old -> compute new env/cmd -> (equal? idempotent no-op)
 *   -> write 0600 env-file -> stop unit -> rename old -> docker create new
 *   (same ports, binds, log opts, user as the old one) -> start (if it was running)
 *   -> wait for the port -> VERIFY (env, cmd, binds and ports read back) -> remove old
 *
 * Supervisor: under systemd (`unit` set) it stops/starts the UNIT (never docker
 * directly — see resolveGameUnit in worker/game-config.ts); with no unit it falls
 * back to docker's own restart policy exactly like recreateGameContainer.
 *
 * Secrets: values travel in the 0600 env-file and are never put in a command
 * line; every failure note is built from fixed strings.
 */

export type RecreateOpts = {
  container: string;
  unit: string | null;
  /** Env changes: a string sets the variable, null removes it. */
  env?: Record<string, string | null>;
  /** Transform the container's launch args (Cmd). */
  cmd?: (old: string[]) => string[];
  /** Guest path for the transient 0600 env-file (removed after create). */
  envFile: string;
  /** Wait for the game port after start. Not fatal while the container is still running. */
  waitPort(): Promise<{ ok: boolean } | null>;
};

export type RecreateResult =
  | { status: "noop" }
  | { status: "recreated"; wasActive: boolean; notes: string[] }
  | { status: "failed"; note: string; rolledBack: boolean };

type Inspected = {
  image: string;
  env: Map<string, string>;
  cmd: string[];
  entrypoint: string[] | null;
  user: string;
  binds: string[];
  ports: string[];
  logOpts: Record<string, string>;
};

function parseInspect(stdout: string): Inspected | null {
  try {
    const o = JSON.parse(stdout.trim());
    const env = new Map<string, string>();
    for (const e of (o.Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) env.set(e.slice(0, i), e.slice(i + 1));
    }
    env.delete("PATH");
    const pb = (o.HostConfig?.PortBindings ?? {}) as Record<string, { HostIp?: string; HostPort?: string }[] | null>;
    const ports: string[] = [];
    for (const [cp, list] of Object.entries(pb)) {
      for (const b of list ?? []) {
        const [port, proto = "tcp"] = cp.split("/");
        ports.push(`${b.HostIp ? b.HostIp + ":" : ""}${b.HostPort ?? ""}:${port}/${proto}`);
      }
    }
    return {
      image: String(o.Config?.Image ?? ""),
      env,
      cmd: (o.Config?.Cmd ?? []) as string[],
      entrypoint: (o.Config?.Entrypoint ?? null) as string[] | null,
      user: String(o.Config?.User ?? ""),
      binds: ((o.HostConfig?.Binds ?? []) as string[]).slice().sort(),
      ports: ports.sort(),
      logOpts: (o.HostConfig?.LogConfig?.Config ?? {}) as Record<string, string>,
    };
  } catch {
    return null;
  }
}

const inspect = (g: Guest, name: string) => g.exec(`docker inspect ${shq(name)} --format '{{json .}}'`);

async function isRunning(g: Guest, name: string): Promise<boolean> {
  const r = await g.exec(`docker inspect -f '{{.State.Running}}' ${shq(name)} 2>/dev/null`);
  return r.stdout.trim() === "true";
}

export async function recreateWithEnv(guest: Guest, o: RecreateOpts): Promise<RecreateResult> {
  const { container: c, unit } = o;
  const old = `${c}-old`;
  const fail = (note: string, rolledBack = false): RecreateResult => ({ status: "failed", note, rolledBack });

  // 0. Self-heal a half-finished earlier run (container missing, `-old` present).
  let insp = await inspect(guest, c);
  if (insp.code !== 0) {
    const oldInsp = await inspect(guest, old);
    if (oldInsp.code !== 0) return fail(`Could not find the "${c}" game container, so nothing was changed.`);
    const r = await guest.exec(`docker rename ${shq(old)} ${shq(c)}`);
    if (r.code !== 0) return fail(`Could not find the "${c}" game container, so nothing was changed.`);
    insp = await inspect(guest, c);
  }
  const cur = parseInspect(insp.stdout);
  if (!cur || !cur.image) return fail("Could not read the game container's settings, so nothing was changed.");

  // 1. Image defaults, so only user-set env is carried (and Entrypoint is only passed if overridden).
  let imgEnv = new Map<string, string>();
  let imgEntry: string[] | null | undefined;
  const ii = await guest.exec(`docker image inspect ${shq(cur.image)} --format '{{json .Config}}'`);
  if (ii.code === 0) {
    try {
      const cfg = JSON.parse(ii.stdout.trim());
      for (const e of (cfg.Env ?? []) as string[]) {
        const i = e.indexOf("=");
        if (i > 0) imgEnv.set(e.slice(0, i), e.slice(i + 1));
      }
      imgEntry = cfg.Entrypoint ?? null;
    } catch {
      imgEnv = new Map();
    }
  }

  // 2. Desired state + idempotent no-op.
  const wantEnv = new Map(cur.env);
  for (const [k, v] of Object.entries(o.env ?? {})) (v === null ? wantEnv.delete(k) : wantEnv.set(k, v));
  const wantCmd = o.cmd ? o.cmd(cur.cmd) : cur.cmd;
  const envSame = [...wantEnv].every(([k, v]) => cur.env.get(k) === v) && [...cur.env.keys()].every((k) => wantEnv.has(k));
  if (envSame && JSON.stringify(wantCmd) === JSON.stringify(cur.cmd)) return { status: "noop" };

  // 3. Build the create command from the OLD container's own config.
  const carried = [...wantEnv].filter(([k, v]) => imgEnv.get(k) !== v);
  const envText = carried.map(([k, v]) => `${k}=${v.replace(/\r?\n/g, " ")}`).join("\n") + (carried.length ? "\n" : "");
  const entryOverridden = !!cur.entrypoint && imgEntry !== undefined && JSON.stringify(cur.entrypoint) !== JSON.stringify(imgEntry);
  const cmdArgs = [...(entryOverridden ? cur.entrypoint!.slice(1) : []), ...wantCmd];
  const create = [
    `docker create --name ${shq(c)}`,
    ...Object.entries(cur.logOpts).map(([k, v]) => `--log-opt ${shq(`${k}=${v}`)}`),
    cur.user ? `--user ${shq(cur.user)}` : "",
    ...cur.ports.map((p) => `-p ${shq(p)}`),
    ...cur.binds.map((b) => `-v ${shq(b)}`),
    `--env-file ${shq(o.envFile)}`,
    entryOverridden ? `--entrypoint ${shq(cur.entrypoint![0])}` : "",
    shq(cur.image),
    ...cmdArgs.map(shq),
  ].filter(Boolean).join(" ");

  // 4. Swap. Everything from here on rolls back on failure.
  const wasActive = unit
    ? (await guest.exec(`systemctl is-active ${shq(unit)}`)).stdout.trim() === "active"
    : await isRunning(guest, c);
  const start = unit ? `systemctl start ${shq(unit)}` : `docker start ${shq(c)}`;
  const stop = unit ? `systemctl stop ${shq(unit)}` : `docker update --restart=no ${shq(c)} 2>/dev/null; docker stop ${shq(c)}`;

  let swapped = false;
  const cleanup = () => guest.exec(`rm -f ${shq(o.envFile)}`).catch(() => undefined);
  const rollback = async (): Promise<boolean> => {
    let ok = true;
    try {
      if (unit) await guest.exec(`systemctl stop ${shq(unit)}`, 120_000);
      if (swapped) {
        const r = await guest.exec(`docker rm -f ${shq(c)} >/dev/null 2>&1; docker rename ${shq(old)} ${shq(c)}`);
        ok = r.code === 0;
      }
      if (wasActive) ok = (await guest.exec(start, 120_000)).code === 0 && ok;
    } catch {
      ok = false;
    }
    await cleanup();
    return ok;
  };
  const failBack = async (why: string): Promise<RecreateResult> => {
    const ok = await rollback();
    return fail(
      ok ? `${why} Your previous configuration was restored.` : `${why} Restoring the previous container also failed — support has been alerted.`,
      ok,
    );
  };

  await guest.exec(`install -m 600 /dev/null ${shq(o.envFile)}`);
  await guest.writeFile(o.envFile, envText);
  const st = await guest.exec(stop, 120_000);
  if (st.code !== 0 || (await isRunning(guest, c))) {
    await cleanup();
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
    return fail("Could not stop the game cleanly, so nothing was changed.");
  }
  const rn = await guest.exec(`docker rm -f ${shq(old)} >/dev/null 2>&1; docker rename ${shq(c)} ${shq(old)}`);
  if (rn.code !== 0) {
    await cleanup();
    if (wasActive) await guest.exec(start, 120_000).catch(() => undefined);
    return fail("Could not replace the game container, so nothing was changed.");
  }
  swapped = true;
  const cr = await guest.exec(create, 120_000);
  await cleanup();
  if (cr.code !== 0) return failBack("Could not create the updated game container.");

  // 5. Start + wait.
  const notes: string[] = [];
  if (wasActive) {
    if ((await guest.exec(start, 120_000)).code !== 0) return failBack("The game did not start with the new settings.");
    const port = await o.waitPort();
    if (!(await isRunning(guest, c))) return failBack("The game did not come back up with the new settings.");
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked — it may still be loading.");
  }

  // 6. Verify by reading the new container back.
  const after = parseInspect((await inspect(guest, c)).stdout);
  const envBad = !after || [...Object.entries(o.env ?? {})].some(([k, v]) => (v === null ? after.env.has(k) : after.env.get(k) !== v));
  const cmdBad = !after || JSON.stringify(after.cmd) !== JSON.stringify(wantCmd);
  const shapeBad = !after || JSON.stringify(after.binds) !== JSON.stringify(cur.binds) || JSON.stringify(after.ports) !== JSON.stringify(cur.ports);
  if (envBad || cmdBad) return failBack("Verification failed: the new container does not carry the new settings.");
  if (shapeBad) return failBack("Verification failed: the new container's ports or volumes differ from the old one.");

  await guest.exec(`docker rm -f ${shq(old)} >/dev/null 2>&1`);
  return { status: "recreated", wasActive, notes };
}
/**
 * INI / CFG patcher. Preserves comments (`;` and `#`), blank lines, key order,
 * unknown keys/sections and the file's line endings; only the requested keys
 * change. A missing key is appended at the end of its section (a missing
 * section is appended at the end of the file). Keys with no section use `section: ""`.
 */

export type IniEdit = { section?: string; key: string; value: string };

const isComment = (l: string) => /^\s*[;#]/.test(l);
const sectionOf = (l: string) => /^\s*\[([^\]]*)\]\s*$/.exec(l)?.[1] ?? null;

export function patchIni(content: string, edits: IniEdit[], opts: { caseSensitive?: boolean } = {}): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const sep = "=";
  const norm = (s: string) => (opts.caseSensitive === false ? s.toLowerCase() : s);
  const lines = content.length ? content.split(/\r?\n/) : [];
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  const done = new Set<number>();

  edits.forEach((e, idx) => {
    const sec = e.section ?? "";
    let cur = "";
    let secStart = sec === "" ? 0 : -1;
    let lastInSec = -1;
    for (let i = 0; i < lines.length; i++) {
      const s = sectionOf(lines[i]);
      if (s !== null) {
        cur = s;
        if (norm(cur) === norm(sec) && secStart < 0) { secStart = i; lastInSec = i; }
        continue;
      }
      if (norm(cur) !== norm(sec)) continue;
      if (!isComment(lines[i]) && lines[i].trim() !== "") lastInSec = i;
      if (isComment(lines[i])) continue;
      const at = lines[i].indexOf("=");
      if (at < 0) continue;
      if (norm(lines[i].slice(0, at).trim()) === norm(e.key)) {
        lines[i] = `${lines[i].slice(0, at).replace(/\s+$/, "")}${sep}${e.value}`;
        done.add(idx);
        return;
      }
    }
    // not found: append
    if (sec === "") {
      // before the first section header, after the last top-level key
      let at = lines.findIndex((l) => sectionOf(l) !== null);
      if (at < 0) at = lines.length;
      lines.splice(at, 0, `${e.key}${sep}${e.value}`);
    } else if (secStart >= 0) {
      lines.splice((lastInSec < 0 ? secStart : lastInSec) + 1, 0, `${e.key}${sep}${e.value}`);
    } else {
      if (lines.length && lines[lines.length - 1].trim() !== "") lines.push("");
      lines.push(`[${sec}]`, `${e.key}${sep}${e.value}`);
    }
  });
  return lines.join(eol) + eol;
}

/** Read one value; undefined if absent. */
export function readIni(content: string, section: string, key: string, caseSensitive = true): string | undefined {
  const norm = (s: string) => (caseSensitive ? s : s.toLowerCase());
  let cur = "";
  for (const l of content.split(/\r?\n/)) {
    const s = sectionOf(l);
    if (s !== null) { cur = s; continue; }
    if (isComment(l) || norm(cur) !== norm(section)) continue;
    const eq = l.indexOf("=");
    if (eq >= 0 && norm(l.slice(0, eq).trim()) === norm(key)) return l.slice(eq + 1).trim();
  }
  return undefined;
}
/**
 * JSON config patcher (TShock config.json, Enshrouded/Core Keeper style files).
 * Parses, sets only the requested paths, serialises with the file's own indent;
 * every key it was not asked to touch (and the key order) is preserved.
 * JSON has no comments, so none are lost; a file that is not valid JSON throws
 * and the caller writes nothing.
 */

export type JsonEdit = { path: string[]; value: unknown };

function detectIndent(content: string): string | number {
  const m = /\n([ \t]+)"/.exec(content);
  if (!m) return 2;
  return m[1].startsWith("\t") ? "\t" : m[1].length;
}

/** Apply edits. `root` (optional) is a wrapper object key: used when the file has it as an object (TShock's "Settings"). */
export function patchJson(content: string, edits: JsonEdit[], opts: { wrapper?: string } = {}): string {
  const doc = JSON.parse(content) as unknown;
  if (doc === null || typeof doc !== "object" || Array.isArray(doc)) throw new Error("config root is not a JSON object");
  let root = doc as Record<string, unknown>;
  if (opts.wrapper) {
    const w = root[opts.wrapper];
    if (w && typeof w === "object" && !Array.isArray(w)) root = w as Record<string, unknown>;
    // else: a flat file (older layout) — patch the root; the game wraps it itself.
  }
  for (const e of edits) {
    let cur = root;
    for (let i = 0; i < e.path.length - 1; i++) {
      const k = e.path[i];
      const next = cur[k];
      if (next === undefined || next === null || typeof next !== "object" || Array.isArray(next)) cur[k] = {};
      cur = cur[k] as Record<string, unknown>;
    }
    cur[e.path[e.path.length - 1]] = e.value;
  }
  const trailingNewline = content.endsWith("\n");
  return JSON.stringify(doc, null, detectIndent(content)) + (trailingNewline ? "\n" : "");
}

/** Read the value at a path (same wrapper rule as patchJson); undefined if absent. */
export function readJson(content: string, path: string[], opts: { wrapper?: string } = {}): unknown {
  let cur: unknown = JSON.parse(content);
  if (opts.wrapper && cur && typeof cur === "object" && !Array.isArray(cur)) {
    const w = (cur as Record<string, unknown>)[opts.wrapper];
    if (w && typeof w === "object" && !Array.isArray(w)) cur = w;
  }
  for (const k of path) {
    if (cur === null || typeof cur !== "object") return undefined;
    cur = (cur as Record<string, unknown>)[k];
  }
  return cur;
}
/**
 * KEY=VALUE patcher (server.properties and friends). Moved verbatim from
 * worker/game-config.ts so appliers can use it without importing the SSH/DB layer.
 */

/** Update `key=value` lines in place, preserving comments/unknown lines; append missing keys. */
export function updateKeyValue(content: string, updates: Record<string, string>): string {
  const lines = content.split(/\r?\n/);
  const seen = new Set<string>();
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("!")) continue;
    const eq = lines[i].indexOf("=");
    if (eq < 0) continue;
    const key = lines[i].slice(0, eq).trim();
    if (Object.prototype.hasOwnProperty.call(updates, key)) {
      lines[i] = `${key}=${updates[key]}`;
      seen.add(key);
    }
  }
  for (const k of Object.keys(updates)) {
    if (!seen.has(k)) lines.push(`${k}=${updates[k]}`);
  }
  return lines.join("\n");
}

/** Read a `key=value` file into a map (comments/blank lines ignored). */
export function parseKeyValue(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t.startsWith("#") || t.startsWith("!")) continue;
    const eq = line.indexOf("=");
    if (eq < 0) continue;
    out[line.slice(0, eq).trim()] = line.slice(eq + 1).trim();
  }
  return out;
}
/**
 * Compare what we meant to write with what we read back from the guest.
 * Returns KEY NAMES only — never values — so a mismatch report can never leak
 * a password into a note, log or job result.
 */
export function verifyReadback(
  expected: Record<string, unknown>,
  actual: Record<string, unknown>,
): { ok: boolean; mismatched: string[] } {
  const mismatched = Object.keys(expected).filter((k) => String(actual[k] ?? "") !== String(expected[k] ?? ""));
  return { ok: mismatched.length === 0, mismatched };
}

/**
 * Game config appliers — the CLIENT-SAFE half (pure data, no I/O, no node imports).
 *
 * Every family that can really push its Settings page into the running game has
 * ONE spec here (the declaration of which schema fields it handles and how each
 * takes effect) and ONE applier in worker/game-config-appliers/<family>.ts (the
 * code that does it). The settings page, `canApplyConfig`, `LIVE_APPLY_FIELDS` and
 * `fieldAppliesLive` (lib/game-config.ts) are all DERIVED from `APPLIER_SPECS`,
 * and the worker's registry reads the very same spec object, so what the page
 * promises and what the worker does cannot drift. Guide: docs/DOCUMENTATION.md,
 * "Game config appliers".
 */

/**
 * How one schema field reaches the running game:
 *  - "live"     applied on save, no restart (rcon / live command)
 *  - "recreate" applied on save by rebuilding the container (a brief restart is part of the apply)
 *  - "restart"  written on save, in effect after the server restarts ("Apply & restart")
 * A schema field that is NOT listed in a spec is "saved only" and the page says so.
 */
export type FieldWhen = "live" | "recreate" | "restart";

export type FieldApply = {
  when: FieldWhen;
  /** Shown under the field. Use it for honest caveats (e.g. "creates a new world; your current world is kept"). */
  note?: string;
  /** The value is a credential: it is redacted from every note/log the framework produces. */
  secret?: boolean;
};

export type GameConfigApplierSpec = {
  family: string;
  /** schema field key -> mechanism. THE source of truth for per-field honesty. */
  fields: Record<string, FieldApply>;
};

import { TERRARIA_SPEC } from "./game-applier-specs/terraria";

/** ONE line per family. The worker registry (worker/game-config-appliers/index.ts) must register the same spec. */
export const APPLIER_SPECS: Record<string, GameConfigApplierSpec> = {
  terraria: TERRARIA_SPEC,
};

/** Whether the applier framework is enabled (kill switch: NXEON_GAMECFG_APPLIERS=off). */
export function appliersEnabled(): boolean {
  return process.env.NXEON_GAMECFG_APPLIERS !== "off";
}

export function applierSpec(family: string | null | undefined): GameConfigApplierSpec | null {
  if (!family || !appliersEnabled()) return null;
  return APPLIER_SPECS[family] ?? null;
}

/** The mechanism for one field, or null when the field is saved only (or the family has no applier). */
export function applierFieldApply(family: string | null | undefined, key: string): FieldApply | null {
  return applierSpec(family)?.fields[key] ?? null;
}
import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Terraria (ryshe/terraria = vanilla Terraria 1.4.5.6 + TShock 6.1) — PURE half:
 * the field spec plus every mapping the worker applier and the provisioning
 * script share, so a fresh install, a reinstall and a Settings save all produce
 * the same server. No I/O here.
 *
 * Where each schema field really lives (read off the image's bootstrap.sh, the
 * provisioning script in lib/terraria-plugins.ts, and TShock's own source):
 *
 *  - world-size / world-name / world-seed / difficulty: Terraria launch args
 *    `-autocreate N -worldname X -seed S -difficulty D`. They are read ONLY when
 *    the world file named by env WORLD_FILENAME does not exist yet. They never
 *    change an existing world. So the applier does what Valheim does: a new
 *    combination gets its OWN world file (name derived from the combination),
 *    the container is recreated pointing at it, and the previous world file is
 *    left on disk untouched. Choosing the old combination again switches back.
 *  - server-password, max-players, server-name, pvp-mode, spawn-protection,
 *    auto-save, kick-mediumcore-on-death: TShock keys in /opt/terraria/config.json
 *    (the host folder mounted at /tshock/tshock, TShock's -configpath). TShock
 *    reads them at startup, so they need a restart. There is NO -password launch
 *    arg in play on purpose: a CLI password would override config.json forever
 *    (TShock.OnPostInit/OnConfigRead), so config.json is the single place.
 */

