test("canApplyConfig / LIVE_APPLY_FIELDS / fieldAppliesLive are derived from the spec", () => {
  for (const [family, spec] of Object.entries(APPLIER_SPECS)) {
    assert.ok(REAL_APPLY_FAMILIES.has(family) && canApplyConfig(family));
