/** env var name -> value (null = unset) for the requested schema fields. */
export function envFor(defs: Record<string, EnvFieldDef>, values: V, only?: readonly string[]): Record<string, string | null> {
  const out: Record<string, string | null> = {};
  for (const [field, d] of Object.entries(defs)) {
    if (only && !only.includes(field)) continue;
    out[d.env] = d.value(values);
  }
  return out;
}

const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

/**
 * Bake env vars into a game setup script for a fresh install / reinstall. Only ADDS variables the
 * script does not declare yet and only when the value is non-null: the ones the script already
 * declares as `-e KEY=` are substituted by applyGameConfigEnv (worker/game-variant.ts) from the
 * schema's key/envKey. Single-quoted and escaped, so a customer value cannot break out. Inserted
 * right after `docker run -d` (the same spot applyGameVariant uses for TYPE).
 */
export function addMissingEnv(setupScript: string, env: Record<string, string | null>): string {
  const flags: string[] = [];
  for (const [k, v] of Object.entries(env)) {
    if (v === null) continue;
    if (new RegExp(`-e\\s+${k}=`).test(setupScript)) continue;
    flags.push(`-e ${k}=${q(v)}`);
  }
  if (!flags.length) return setupScript;
  return setupScript.replace(/(docker run\s+(?:-d|--detach)\b)/, `$1 ${flags.join(" ")}`);
}

