    maxPlayers: { when: "recreate" },
    gameId: { when: "recreate", note: "Must be 15-28 letters/digits; anything else makes the game generate a new code at every start." },
    password: { when: "recreate", secret: true, note: "Up to 28 characters; longer is refused. Blank makes the game generate a random password at each start." },
    worldMode: { when: "recreate", note: "Passed to the game on every start. Core Keeper applies the mode when a world is created; an existing world may keep its own mode (and Creative cannot be converted)." },
  },
};

