export function corekeeperProblems(values: V, touched: readonly string[]): string[] {
  const out: string[] = [];
  const pw = String(values.password ?? "");
  if (touched.includes("password") && pw.length > COREKEEPER_PASSWORD_MAX) out.push(`The password is longer than ${COREKEEPER_PASSWORD_MAX} characters, so it was not applied (the game would ignore it and make a random one).`);
  const id = String(values.gameId ?? "").trim();
  if (touched.includes("gameId") && id && !/^[A-Za-z0-9]{15,28}$/.test(id)) out.push("The connect code must be 15-28 letters/digits, so it was not applied.");
  return out;
}
