import type { GameConfigApplierSpec } from "../game-config-appliers";
import type { JsonEdit } from "../../worker/game-config-appliers/kit/json-patch";
import type { V } from "./env-fields";

/**
 * Factorio (factoriotools/factorio) — PURE half. (Type-only import above: no runtime dependency on the worker.)
 *
 * Read off the image's docker-entrypoint.sh: the image does NOT turn env vars into server settings
 * ("prefer configuration files"). On first start it copies the game's server-settings.example.json
 * to /factorio/config/server-settings.json (host: /opt/factorio/config/) and starts the game with
 * `--server-settings` pointing at it and `--server-adminlist /factorio/config/server-adminlist.json`.
 * The game reads both files at startup, so every field here is "restart".
 *
 *  - name, description, max_players, game_password, autosave_interval, autosave_slots,
 *    non_blocking_saving, afk_autokick_interval, allow_commands: top-level keys of server-settings.json
 *    (allow_commands is written as a JSON boolean for Everyone/Nobody and the string "admins-only").
 *  - visibility: the schema's checkbox is `visibility.public` (the sibling `lan` is left alone).
 *    Factorio only lists a server publicly with a factorio.com account, whose `username` and
 *    `token` live in the same file (the Mods tab reads them from there). Turning it ON without them
 *    would break the start, so it is only written when both are present; otherwise it is left as is
 *    and the customer is told why. Turning it OFF is always written.
 *  - admins: server-adminlist.json is the file the image passes to the game (a JSON array of
 *    usernames). It is written WHOLE from this field, so promotions made in-game with /promote are
 *    replaced when the field is saved.
 */
export const FACTORIO_SPEC: GameConfigApplierSpec = {
  family: "factorio",
  fields: {
