export const BAROTRAUMA_OWNER_FIELDS = ["OWNER_STEAMNAME", "OWNER_STEAMID"] as const;
export const BAROTRAUMA_ENV: Record<string, EnvFieldDef> = {
  INSTALL_LUA: { env: "INSTALL_LUA", value: (v) => boolTrueOrNull(v.INSTALL_LUA) },
};

export const BAROTRAUMA_SPEC: GameConfigApplierSpec = {
  family: "barotrauma",
  fields: {
    SERVERNAME: { when: "recreate", note: "Written into the server's own settings file; your server restarts briefly." },
    PASSWORD: { when: "recreate", secret: true, note: "Written into the server's own settings file; your server restarts briefly. Blank removes the password." },
    MAX_PLAYERS: { when: "recreate" },
    PUBLICITY: { when: "recreate" },
    OWNER_STEAMNAME: { when: "recreate", note: "Needs both the Steam name and the SteamID. Adds that account as host with all permissions; an owner entered earlier is not removed from the file." },
    OWNER_STEAMID: { when: "recreate", note: "Needs both the Steam name and the SteamID. Adds that account as host with all permissions; an owner entered earlier is not removed from the file." },
    INSTALL_LUA: { when: "recreate", note: "Installs Lua/C# support at the next start. Turning it off stops re-installing it; already installed files are not removed (use Wipe & reinstall for that)." },
  },
};

/** The attribute name the game's own file uses for each settings field, and its value. */
export function barotraumaSettingsAttrs(values: V, only?: readonly string[]): Record<string, string> {
  const want = (k: string) => !only || only.includes(k);
  const out: Record<string, string> = {};
  if (want("SERVERNAME")) out.name = String(values.SERVERNAME ?? "").trim() || "Nxeon Barotrauma";
  if (want("PASSWORD")) out.password = String(values.PASSWORD ?? "");
  if (want("MAX_PLAYERS")) out.MaxPlayers = String(Math.trunc(Number(values.MAX_PLAYERS ?? 10)));
  if (want("PUBLICITY")) out.IsPublic = values.PUBLICITY === true || values.PUBLICITY === "true" ? "True" : "False";
  return out;
}

const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const unesc = (s: string) => s.replace(/&quot;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");

/** [start, end] of the opening tag `<tag ...>` (end = index of its `>`), quote-aware; null if absent. */
function openTag(xml: string, tag: string, from = 0): [number, number] | null {
  const m = new RegExp(`<${tag}(?=[\\s>/])`, "i").exec(xml.slice(from));
  if (!m) return null;
  const start = from + m.index;
  let quote = "";
  for (let i = start; i < xml.length; i++) {
    const c = xml[i];
    if (quote) { if (c === quote) quote = ""; continue; }
    if (c === '"' || c === "'") quote = c;
    else if (c === ">") return [start, i];
  }
  return null;
}

const attrRe = (name: string) => new RegExp(`(\\s)(${name})(\\s*=\\s*)("[^"]*"|'[^']*')`, "i");

/** Set attributes on a tag's start (case-insensitive match, original name kept; missing ones appended). */
function setTagAttrs(tagText: string, attrs: Record<string, string>): string {
  let t = tagText;
  for (const [name, value] of Object.entries(attrs)) {
    const re = attrRe(name);
    if (re.test(t)) t = t.replace(re, (_m, ws, n, eq) => `${ws}${n}${eq}"${esc(value)}"`);
    else t = t.replace(/\s*(\/?>)$/, (_m, end) => `\n  ${name}="${esc(value)}"${end === "/>" ? " />" : ">"}`);
  }
  return t;
}

/** Patch the attributes of the FIRST `<tag ...>` start tag. Throws if the tag is missing. */
export function patchXmlRootAttrs(xml: string, tag: string, attrs: Record<string, string>): string {
  const r = openTag(xml, tag);
  if (!r) throw new Error(`no <${tag}> element`);
  return xml.slice(0, r[0]) + setTagAttrs(xml.slice(r[0], r[1] + 1), attrs) + xml.slice(r[1] + 1);
}

export function readXmlRootAttr(xml: string, tag: string, name: string): string | undefined {
  const r = openTag(xml, tag);
  if (!r) return undefined;
  const m = attrRe(name).exec(xml.slice(r[0], r[1] + 1));
  return m ? unesc(m[4].slice(1, -1)) : undefined;
}

/**
 * clientpermissions.xml: make sure a `<Client name steamid permissions="All">` exists for this
 * SteamID (updating the name/permissions when it is there already). Other clients are never touched.
 */
export function ensureOwnerClient(xml: string, name: string, steamId: string): string {
  let from = 0;
  for (;;) {
    const r = openTag(xml, "Client", from);
    if (!r) break;
    const text = xml.slice(r[0], r[1] + 1);
    const m = attrRe("steamid").exec(text);
    if (m && unesc(m[4].slice(1, -1)) === steamId) {
      return xml.slice(0, r[0]) + setTagAttrs(text, { name, permissions: "All" }) + xml.slice(r[1] + 1);
    }
    from = r[1] + 1;
  }
  const entry = `  <Client\n    name="${esc(name)}"\n    steamid="${esc(steamId)}"\n    permissions="All">\n  </Client>\n`;
  if (/<ClientPermissions\s*\/>/i.test(xml)) return xml.replace(/<ClientPermissions\s*\/>/i, `<ClientPermissions>\n${entry}</ClientPermissions>`);
  const close = /<\/ClientPermissions\s*>/i.exec(xml);
  if (!close) throw new Error("no <ClientPermissions> element");
  return xml.slice(0, close.index) + entry + xml.slice(close.index);
}

/** True when the permissions file has a Client with this SteamID, this name and "All". */
export function ownerClientPresent(xml: string, name: string, steamId: string): boolean {
  let from = 0;
  for (;;) {
    const r = openTag(xml, "Client", from);
    if (!r) return false;
    const text = xml.slice(r[0], r[1] + 1);
    const sid = attrRe("steamid").exec(text);
    if (sid && unesc(sid[4].slice(1, -1)) === steamId) {
      const nm = attrRe("name").exec(text);
      const pm = attrRe("permissions").exec(text);
      return !!nm && unesc(nm[4].slice(1, -1)) === name && !!pm && unesc(pm[4].slice(1, -1)) === "All";
    }
    from = r[1] + 1;
  }
}

/** Steam name / id values the XML (and the game) can carry; anything else is refused by the applier. */
export const barotraumaOwnerOk = (name: string, id: string) => name.trim() !== "" && /^[A-Za-z0-9_:]{3,40}$/.test(id.trim()) && !/[\r\n]/.test(name);
