 * Barotrauma needs nothing here: its settings files are patched by the applier right after the first
 * start (worker/index.ts auto-queues a GAME_CONFIG job for any non-default value).
 */
export function applyCoopFamilySetup(setupScript: string, family: string | null, gameConfig: unknown): string {
  if (!family || !gameConfig) return setupScript;
  if (!["factorio", "satisfactory", "corekeeper", "necesse", "barotrauma"].includes(family)) return setupScript;
  const v = validateConfig(family, gameConfig as Record<string, unknown>);
  if (!v.ok) return setupScript;
  const values = v.values as V;
  switch (family) {
    case "factorio": return applyFactorioSetup(setupScript, values);
    case "satisfactory": return addMissingEnv(setupScript, satisfactoryEnv(values));
    case "corekeeper": return addMissingEnv(setupScript, corekeeperEnv(values));
    case "necesse": return addMissingEnv(setupScript, necesseEnv(values));
    case "barotrauma": return addMissingEnv(setupScript, envFor(BAROTRAUMA_ENV, values));
    default: return setupScript;
  }
}
EOF

