import type { ApplierContext, ApplyOutcome, Guest } from "./types";
import { shq } from "./types";
import { recreateWithEnv } from "./kit/env-recreate";

/**
 * Shared applier body for families whose settings are container env vars that the image turns into
 * launch args on every start (satisfactory, abioticfactor, corekeeper, necesse). It owns the part that
 * is easy to get wrong: not rebuilding the container when nothing differs.
 *
 *   read the container's current env -> for each touched field decide set / unset / leave
 *   (an unset var and an empty one are the same to these images, so "blank" never forces a rebuild)
 *   -> recreateWithEnv (old container kept until the new one verifies; rolls back on any failure)
 *
 * Values never appear in a note: messages name the schema fields only.
 */
export type EnvApplyOpts = {
  container: string;
  envFile: string;
  /** env var name -> desired value (null = must be absent), for the touched fields only. */
  desired: Record<string, string | null>;
  /** schema field label per env var, for messages. */
  labels: Record<string, string>;
};

async function currentEnv(guest: Guest, container: string): Promise<Map<string, string> | null> {
  const r = await guest.exec(`docker inspect ${shq(container)} --format '{{json .}}'`);
  if (r.code !== 0) return null;
  try {
    const o = JSON.parse(r.stdout.trim());
    const m = new Map<string, string>();
    for (const e of (o.Config?.Env ?? []) as string[]) {
      const i = e.indexOf("=");
      if (i > 0) m.set(e.slice(0, i), e.slice(i + 1));
    }
    return m;
  } catch {
    return null;
  }
}

/** Env changes that would really alter the container: unset+absent/empty and equal values are dropped. */
export function envDiff(cur: Map<string, string>, desired: Record<string, string | null>): Record<string, string | null> {
  const out: Record<string, string | null> = {};
  for (const [k, v] of Object.entries(desired)) {
    const have = cur.get(k);
    if (v === null) {
      if (have !== undefined && have !== "") out[k] = null;
    } else if (v === "") {
      if (have !== undefined && have !== "") out[k] = "";
    } else if (have !== v) out[k] = v;
  }
  return out;
}

export async function applyEnvFields(ctx: ApplierContext, o: EnvApplyOpts): Promise<ApplyOutcome> {
  const cur = await currentEnv(ctx.guest, o.container);
  if (!cur) return { ok: false, applied: [], notes: [`Could not read the "${o.container}" game container, so nothing was changed.`] };
  const diff = envDiff(cur, o.desired);
  const names = Object.keys(diff).map((k) => o.labels[k] ?? k);
  if (!names.length) return { ok: true, applied: [], notes: ["The server already has these settings, so nothing needed to change."] };

  const r = await recreateWithEnv(ctx.guest, {
    container: o.container,
    unit: ctx.unit,
    env: diff,
    envFile: o.envFile,
    waitPort: ctx.waitPort,
  });
  if (r.status === "failed") return { ok: false, applied: [], notes: [r.note, "Nothing was changed on your server."] };
  if (r.status === "noop") return { ok: true, applied: [], notes: ["The server already has these settings, so nothing needed to change."] };
  const notes = [...r.notes];
  if (r.wasActive) notes.push("Your server restarted briefly to apply this — connected players were disconnected and can rejoin now.");
  else notes.push("Your server is stopped, so the new settings will be used the next time you start it.");
  return { ok: true, applied: [`Applied ${names.join(", ")} to your server.`], notes, restarted: r.wasActive };
}
EOF
