import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { applyEnvFields, envLabels } from "./env-fields";
import { COREKEEPER_SPEC, COREKEEPER_CONTAINER, COREKEEPER_ENV, corekeeperEnv } from "../../lib/game-applier-specs/corekeeper";
import { corekeeperProblems } from "../../lib/game-applier-specs/corekeeper";

/**
 * Core Keeper applier: env-recreate through the shared helper (./env-fields.ts). Mechanism and the
 * reasons for it: lib/game-applier-specs/corekeeper.ts.
 */
const ENV_FILE = "/root/corekeeper.env";

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  // A value the game would silently ignore is held back (and said so) instead of being "applied".
  const problems = corekeeperProblems(ctx.values, ctx.touched);
  const held = new Set<string>([...(problems.some((p) => /password/i.test(p)) ? ["password"] : []), ...(problems.some((p) => /connect code/i.test(p)) ? ["gameId"] : [])]);
  const touched = ctx.touched.filter((k) => !held.has(k));
  if (!touched.length) return { ok: false, applied: [], notes: [...problems, "Nothing was changed on your server."] };
  const out = await applyEnvFields(ctx, { container: COREKEEPER_CONTAINER, envFile: ENV_FILE, desired: corekeeperEnv(ctx.values, touched), labels: envLabels("corekeeper", COREKEEPER_ENV) });
  return { ...out, notes: [...problems, ...out.notes] };
  return applyEnvFields(ctx, { container: COREKEEPER_CONTAINER, envFile: ENV_FILE, desired: corekeeperEnv(ctx.values, ctx.touched), labels: envLabels("corekeeper", COREKEEPER_ENV) });
}

export const corekeeperApplier: GameConfigApplier = { spec: COREKEEPER_SPEC, apply };

