import { FACTORIO_SPEC, FACTORIO_SETTINGS_PATH, FACTORIO_ADMINLIST_PATH, factorioAdminList, factorioEdits, factorioHasPublishCredentials } from "../../lib/game-applier-specs/factorio";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { shq } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { patchJson, readJson } from "./kit/json-patch";

/**
 * Factorio applier — config-file strategy on /opt/factorio/config/server-settings.json (+
 * server-adminlist.json for the admins field). The game reads both at startup, so every field takes
 * effect on the next start; the job layer restarts when the customer chose "Apply & restart".
 * Mechanism, the visibility/credentials rule and the admin-list semantics: lib/game-applier-specs/factorio.ts.
 */

function validateJsonObject(content: string): string | null {
  try {
    const d = JSON.parse(content);
    return d && typeof d === "object" && !Array.isArray(d) ? null : "The result is not a JSON object.";
  } catch {
    return "The result is not valid JSON.";
  }
}
const validateAdminList = (content: string): string | null => {
  try {
    const d = JSON.parse(content);
    return Array.isArray(d) && d.every((x) => typeof x === "string") ? null : "The admin list is not a JSON array of names.";
  } catch {
    return "The admin list is not valid JSON.";
  }
};

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const settingsFields = ctx.touched.filter((k) => k !== "admins");
  const adminsTouched = ctx.touched.includes("admins");
  const applied: string[] = [];
  const notes: string[] = [];
  const undo: (() => Promise<void>)[] = [];
  const commits: (() => Promise<void>)[] = [];
  const fail = async (msg: string): Promise<ApplyOutcome> => {
    for (const u of undo.reverse()) await u().catch(() => undefined);
    return { ok: false, applied: [], notes: [msg, "Nothing was changed on your server."] };
  };

  // ---- server-settings.json ------------------------------------------------
  if (settingsFields.length) {
    const raw = await guest.readFile(FACTORIO_SETTINGS_PATH);
    let canPublish = false;
    try { canPublish = raw !== null && factorioHasPublishCredentials(JSON.parse(raw)); } catch { /* handled by the patcher below */ }
    let edits = factorioEdits(values, settingsFields, { canPublish });
    if (settingsFields.includes("visibility") && values.visibility === true && !canPublish) {
      notes.push("Public listing was left off: Factorio only lists a server publicly with your factorio.com username and token in the server's settings file (the same ones the Mods tab uses).");
    }
    const res = await patchRemoteFile(guest, {
      path: FACTORIO_SETTINGS_PATH,
      patch: (old) => patchJson(old, edits),
      validate: validateJsonObject,
    });
    if (res.status === "invalid" || res.status === "failed") return fail(res.reason);
    if (res.status === "missing") {
      notes.push(`Factorio hasn't created its settings file yet (the server has never fully started), so these were saved but not applied: ${settingsFields.join(", ")}. Start the server once, then save again.`);
    } else if (res.status === "unchanged") {
      notes.push("Factorio's settings file already matched — nothing to change there.");
    } else {
      undo.push(res.restore);
      commits.push(res.commit);
      const back = await guest.readFile(FACTORIO_SETTINGS_PATH);
      const bad: string[] = [];
      for (const e of edits) {
        const got = back === null ? undefined : readJson(back, e.path);
        if (JSON.stringify(got) !== JSON.stringify(e.value)) bad.push(e.path.join("."));
      }
      if (bad.length) return fail(`Verification failed for ${bad.join(", ")}; the previous settings file was restored.`);
      applied.push(`Updated Factorio's server settings (${settingsFields.join(", ")}).`);
    }
  }

  // ---- server-adminlist.json (written whole from the field) --------------------
  if (adminsTouched) {
    const list = factorioAdminList(values.admins);
    const want = JSON.stringify(list, null, 2) + "\n";
    const existing = await guest.readFile(FACTORIO_ADMINLIST_PATH);
    if (existing === null) {
      try {
        await guest.writeFile(FACTORIO_ADMINLIST_PATH, want);
        undo.push(async () => void (await guest.exec(`rm -f ${shq(FACTORIO_ADMINLIST_PATH)}`)));
      } catch {
        return fail("Could not write Factorio's admin list.");
      }
    } else {
      const res = await patchRemoteFile(guest, { path: FACTORIO_ADMINLIST_PATH, patch: () => want, validate: validateAdminList });
      if (res.status === "invalid" || res.status === "failed") return fail(res.reason);
      if (res.status === "changed") { undo.push(res.restore); commits.push(res.commit); }
    }
    const back = await guest.readFile(FACTORIO_ADMINLIST_PATH);
    let ok = false;
    try { ok = back !== null && JSON.stringify(JSON.parse(back)) === JSON.stringify(list); } catch { /* not ok */ }
    if (!ok) return fail("Verification failed for the admin list; the previous list was restored.");
    if (existing !== null && existing === want) notes.push("The admin list already matched — nothing to change there.");
    else applied.push(`Updated the admin list (${list.length} ${list.length === 1 ? "name" : "names"}).`);
  }

  for (const c of commits) await c().catch(() => undefined);
  if (applied.length) notes.push("Factorio reads these files when it starts, so the changes take effect after a restart.");
  return { ok: true, applied, notes };
}

export const factorioApplier: GameConfigApplier = { spec: FACTORIO_SPEC, apply };
EOF

