      if (res.status === "invalid" || res.status === "failed") return fail(res.reason);
      if (res.status === "changed") { undo.push(res.restore); commits.push(res.commit); }
    }
    const back = await guest.readFile(FACTORIO_ADMINLIST_PATH);
    let ok = false;
    try { ok = back !== null && JSON.stringify(JSON.parse(back)) === JSON.stringify(list); } catch { /* not ok */ }
