  for (const c of commits) await c().catch(() => undefined);
  if (applied.length) notes.push("Factorio reads these files when it starts, so the changes take effect after a restart.");
  return { ok: true, applied, notes };
}

export const factorioApplier: GameConfigApplier = { spec: FACTORIO_SPEC, apply };
