import { BAROTRAUMA_CONTAINER, BAROTRAUMA_ENV, BAROTRAUMA_OWNER_FIELDS, BAROTRAUMA_PERMISSIONS_PATH, BAROTRAUMA_SETTINGS_FIELDS, BAROTRAUMA_SETTINGS_PATH, BAROTRAUMA_SPEC, barotraumaOwnerOk, barotraumaSettingsAttrs, ensureOwnerClient, ownerClientPresent, patchXmlRootAttrs, readXmlRootAttr } from "../../lib/game-applier-specs/barotrauma";
import { envFor } from "../../lib/game-applier-specs/env-fields";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { shq } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { recreateWithEnv } from "./kit/env-recreate";
import { envDiff, envLabels } from "./env-fields";

/**
 * Barotrauma applier — mixed. Why (and why NOT env-recreate for the settings): see
 * lib/game-applier-specs/barotrauma.ts. In short, the image only reads SERVERNAME/PASSWORD/... while it
 * first creates serversettings.xml, so the real settings are patched in /opt/barotrauma/config/ with the
 * game stopped (it may rewrite those files while running), then the game is started and the files are
 * read back. INSTALL_LUA is a normal env-recreate (the image reads it on every start).
 *
 *   plan (read + patch in memory; nothing to do = no stop, no restart)
 *   -> stop -> patch serversettings.xml / clientpermissions.xml -> [env-recreate INSTALL_LUA]
 *   -> start (only if it was running) -> wait for the port -> read the files back
 *   Any failure restores the files (and the container) and starts the game again if it was running.
 */
const ENV_FILE = "/root/barotrauma.env";
const validXml = (tag: string) => (c: string): string | null => (new RegExp(`<${tag}[\\s>/]`, "i").test(c) ? null : `The result has no <${tag}> element.`);

async function isRunning(g: ApplierContext["guest"], name: string): Promise<boolean> {
  return (await g.exec(`docker inspect -f '{{.State.Running}}' ${shq(name)} 2>/dev/null`)).stdout.trim() === "true";
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const settingsFields = ctx.touched.filter((k) => (BAROTRAUMA_SETTINGS_FIELDS as readonly string[]).includes(k));
  const ownerTouched = ctx.touched.some((k) => (BAROTRAUMA_OWNER_FIELDS as readonly string[]).includes(k));
  const luaTouched = ctx.touched.includes("INSTALL_LUA");
  const applied: string[] = [];
  const notes: string[] = [];

  const attrs = barotraumaSettingsAttrs(values, settingsFields);
  const ownerName = String(values.OWNER_STEAMNAME ?? "").trim();
  const ownerId = String(values.OWNER_STEAMID ?? "").trim();
  const wantOwner = ownerTouched && ownerName !== "" && ownerId !== "";
  if (ownerTouched && !wantOwner) {
    notes.push(ownerName === "" && ownerId === "" ? "No owner was set (both the Steam name and the SteamID are needed)." : "The owner was not applied: both the Steam name and the SteamID are needed.");
  } else if (wantOwner && !barotraumaOwnerOk(ownerName, ownerId)) {
    notes.push("The owner was not applied: the SteamID may only contain letters, digits, _ and : (for example 76561198012345678).");
  }
  const ownerOk = wantOwner && barotraumaOwnerOk(ownerName, ownerId);

  // ---- plan: which of the three parts would really change something? ----------------
  const settingsOld = settingsFields.length ? await guest.readFile(BAROTRAUMA_SETTINGS_PATH) : null;
  const permsOld = ownerOk ? await guest.readFile(BAROTRAUMA_PERMISSIONS_PATH) : null;
  if (settingsFields.length && settingsOld === null) notes.push(`Barotrauma hasn't created its settings file yet (the server has never fully started), so these were saved but not applied: ${settingsFields.join(", ")}. Start the server once, then save again.`);
  if (ownerOk && permsOld === null) notes.push("Barotrauma hasn't created its permissions file yet (the server has never fully started), so the owner was saved but not applied. Start the server once, then save again.");
  const settingsChange = (() => {
    if (settingsOld === null) return false;
    try { return patchXmlRootAttrs(settingsOld, "serversettings", attrs) !== settingsOld; } catch { return true; /* patchRemoteFile reports it */ }
  })();
  const ownerChange = permsOld !== null && !ownerClientPresent(permsOld, ownerName, ownerId);
  let envDesired: Record<string, string | null> = {};
  if (luaTouched) {
    const insp = await guest.exec(`docker inspect ${shq(BAROTRAUMA_CONTAINER)} --format '{{json .}}'`);
    if (insp.code !== 0) return { ok: false, applied: [], notes: [`Could not find the "${BAROTRAUMA_CONTAINER}" game container, so nothing was changed.`] };
    const cur = new Map<string, string>();
    try { for (const e of (JSON.parse(insp.stdout.trim()).Config?.Env ?? []) as string[]) { const i = e.indexOf("="); if (i > 0) cur.set(e.slice(0, i), e.slice(i + 1)); } } catch { /* leave empty */ }
    envDesired = envDiff(cur, envFor(BAROTRAUMA_ENV, values));
  }
  const envChange = Object.keys(envDesired).length > 0;
  if (!settingsChange && !ownerChange && !envChange) {
    return { ok: true, applied: [], notes: [...notes, "The server already has these settings, so nothing needed to change."] };
  }

  // ---- act: stop -> patch -> (recreate) -> start --------------------------------
  const unit = ctx.unit;
  const wasActive = unit ? (await guest.exec(`systemctl is-active ${shq(unit)}`)).stdout.trim() === "active" : await isRunning(guest, BAROTRAUMA_CONTAINER);
  const startCmd = unit ? `systemctl start ${shq(unit)}` : `docker start ${shq(BAROTRAUMA_CONTAINER)}`;
  const stopCmd = unit ? `systemctl stop ${shq(unit)}` : `docker stop ${shq(BAROTRAUMA_CONTAINER)}`;
  const restores: (() => Promise<void>)[] = [];
  const commits: (() => Promise<void>)[] = [];
  const back = async (why: string): Promise<ApplyOutcome> => {
    for (const r of restores.reverse()) await r().catch(() => undefined);
    let up = true;
    if (wasActive) up = (await guest.exec(startCmd, 120_000)).code === 0;
    return { ok: false, applied: [], notes: [why, up ? "Your previous settings were restored." : "Restoring the previous settings worked, but the server did not start again — support has been alerted."], restarted: wasActive };
  };

  if (wasActive) {
    const st = await guest.exec(stopCmd, 120_000);
    if (st.code !== 0 || (await isRunning(guest, BAROTRAUMA_CONTAINER))) {
      if (st.code === 0) await guest.exec(startCmd, 120_000).catch(() => undefined);
      return { ok: false, applied: [], notes: ["Could not stop the game cleanly, so nothing was changed."] };
    }
  }

  if (settingsChange) {
    const res = await patchRemoteFile(guest, { path: BAROTRAUMA_SETTINGS_PATH, patch: (old) => patchXmlRootAttrs(old, "serversettings", attrs), validate: validXml("serversettings") });
    if (res.status === "invalid" || res.status === "failed") return back(res.reason);
    if (res.status === "changed") { restores.push(res.restore); commits.push(res.commit); applied.push(`Updated the server's settings file (${settingsFields.join(", ")}).`); }
  }
  if (ownerChange) {
    const res = await patchRemoteFile(guest, { path: BAROTRAUMA_PERMISSIONS_PATH, patch: (old) => ensureOwnerClient(old, ownerName, ownerId), validate: validXml("ClientPermissions") });
    if (res.status === "invalid" || res.status === "failed") return back(res.reason);
    if (res.status === "changed") { restores.push(res.restore); commits.push(res.commit); applied.push("Added the owner to the server's permissions file."); }
  }
  if (envChange) {
    const r = await recreateWithEnv(guest, { container: BAROTRAUMA_CONTAINER, unit, env: envDesired, envFile: ENV_FILE, waitPort: ctx.waitPort });
    if (r.status === "failed") return back(r.note);
    if (r.status === "recreated") applied.push(`Applied ${Object.keys(envDesired).map((k) => envLabels("barotrauma", BAROTRAUMA_ENV)[k] ?? k).join(", ")} to your server.`);
  }

  // ---- start, wait, read back ---------------------------------------------------
  if (wasActive) {
    if ((await guest.exec(startCmd, 120_000)).code !== 0) return back("The game did not start with the new settings.");
    const port = await ctx.waitPort();
    if (!(await isRunning(guest, BAROTRAUMA_CONTAINER))) {
      await guest.exec(stopCmd, 120_000).catch(() => undefined);
      return back("The game did not come back up with the new settings.");
    }
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked — it may still be loading.");
  } else {
    notes.push("Your server is stopped, so the new settings will be used the next time you start it.");
  }
  const bad: string[] = [];
  if (settingsChange) {
    const now = await guest.readFile(BAROTRAUMA_SETTINGS_PATH);
    for (const [k, v] of Object.entries(attrs)) if (now === null || readXmlRootAttr(now, "serversettings", k) !== v) bad.push(k);
  }
  if (ownerChange) {
    const now = await guest.readFile(BAROTRAUMA_PERMISSIONS_PATH);
    if (now === null || !ownerClientPresent(now, ownerName, ownerId)) bad.push("owner");
  }
  if (bad.length) {
    // The game rewrote the file while starting; do not claim success.
    notes.push(`After the restart the game's own file no longer matched for ${bad.join(", ")}, so those may not be in effect. Please try saving again or contact support.`);
    return { ok: false, applied, notes, restarted: wasActive };
  }
  for (const c of commits) await c().catch(() => undefined);
  if (wasActive) notes.push("Your server restarted briefly to apply this — connected players were disconnected and can rejoin now.");
  return { ok: true, applied, notes, restarted: wasActive };
}

export const barotraumaApplier: GameConfigApplier = { spec: BAROTRAUMA_SPEC, apply };
