import { fakeGuest, IMAGE_ENV } from "./_fake-docker-guest";
import { runApplier } from "../worker/game-config-appliers/run";
import type { GameConfigApplier } from "../worker/game-config-appliers/types";
import { validateConfig } from "../lib/game-config";

export type Vals = Record<string, string | number | boolean>;

/** A fake guest whose game container looks like the given family's real one (env/cmd/binds/ports/image). */
export function familyGuest(o: {
  container: string;
  unit?: string;
  image: string;
  env: string[];
  cmd?: string[];
  binds: string[];
  ports: Record<string, { HostIp: string; HostPort: string }[]>;
  files?: Record<string, string>;
  active?: boolean;
  createFails?: boolean;
  startFailsForNew?: boolean;
  corruptWrite?: string;
}) {
  const g = fakeGuest({ container: o.container, unit: o.unit ?? `${o.container}.service`, files: o.files, active: o.active, createFails: o.createFails, startFailsForNew: o.startFailsForNew, corruptWrite: o.corruptWrite });
  const c = g.containers.get(o.container)!;
  Object.assign(c, { image: o.image, env: [...IMAGE_ENV, ...o.env], cmd: o.cmd ?? [], binds: o.binds, ports: o.ports, running: o.active ?? true });
  return g;
}

export const defaultsFor = (family: string): Vals => {
  const v = validateConfig(family, {});
  if (!v.ok) throw new Error("defaults invalid");
  return v.values as Vals;
};

export function runFamily(applier: GameConfigApplier, g: ReturnType<typeof familyGuest>, values: Vals, changed: string[] | undefined, restartRequested = false) {
  return runApplier(applier, { server: { id: "s1" }, values, changed, restartRequested, guest: g.guest, unit: g.unit, waitPort: async () => ({ ok: true }) });
}

/** The env map of the game container as the guest now sees it (PATH/image env excluded). */
export function envOf(g: ReturnType<typeof familyGuest>, name = g.name): Record<string, string> {
  const out: Record<string, string> = {};
  for (const e of g.containers.get(name)!.env) {
    const i = e.indexOf("=");
    if (!IMAGE_ENV.includes(e)) out[e.slice(0, i)] = e.slice(i + 1);
  }
  return out;
}
