import { buildGameSetupScript } from "../worker/game-variant";
import { defaultsFor, familyGuest, runFamily } from "./_cfg-coop";

// Shape of the game's own server-settings.example.json (trimmed to what matters here).
const EXAMPLE = JSON.stringify({
  name: "Name of the game as it will appear in the game listing",
  description: "Description of the game that will appear in the listing",
  tags: ["game", "tags"],
  max_players: 0,
  visibility: { public: true, lan: true },
  username: "",
  token: "",
  game_password: "",
  require_user_verification: true,
  allow_commands: "admins-only",
  autosave_interval: 10,
  autosave_slots: 5,
  afk_autokick_interval: 0,
  auto_pause: true,
  non_blocking_saving: false,
  admins: [],
}, null, 2) + "\n";
const guest = (files: Record<string, string> = { [FACTORIO_SETTINGS_PATH]: EXAMPLE }, extra: Partial<Parameters<typeof familyGuest>[0]> = {}) =>
  familyGuest({
    container: "factorio", image: "factoriotools/factorio:stable", env: ["PORT=34197"], binds: ["/opt/factorio:/factorio"],
    ports: { "34197/udp": [{ HostIp: "", HostPort: "34197" }], "27015/tcp": [{ HostIp: "", HostPort: "27015" }] }, files, ...extra,
  });
const run = (g: ReturnType<typeof guest>, over: Record<string, string | number | boolean>, changed: string[] | undefined = Object.keys(over)) =>
  runFamily(factorioApplier, g, { ...defaultsFor("factorio"), ...over }, changed);
const doc = (g: ReturnType<typeof guest>) => JSON.parse(g.files.get(FACTORIO_SETTINGS_PATH)!);

test("every Factorio schema field is mapped, all as restart", () => {
  assert.deepEqual(GAME_CONFIG_SCHEMAS.factorio.fields.map((f) => f.key).sort(), Object.keys(FACTORIO_SPEC.fields).sort());
  for (const f of Object.values(FACTORIO_SPEC.fields)) assert.equal(f.when, "restart");
});

test("each settings field is written to server-settings.json; every other key (tags, username, ...) is preserved; the container is never touched", async () => {
  const cases: [string, string | number | boolean, string, unknown][] = [
    ["name", "My Factory", "name", "My Factory"],
    ["description", "Rocket science", "description", "Rocket science"],
    ["max_players", 24, "max_players", 24],
    ["game_password", "pw-Sekrit9", "game_password", "pw-Sekrit9"],
    ["allow_commands", "true", "allow_commands", true],
    ["allow_commands", "false", "allow_commands", false],
    ["allow_commands", "admins-only", "allow_commands", "admins-only"],
    ["autosave_interval", 5, "autosave_interval", 5],
    ["autosave_slots", 12, "autosave_slots", 12],
    ["non_blocking_saving", true, "non_blocking_saving", true],
    ["afk_autokick_interval", 15, "afk_autokick_interval", 15],
  ];
  for (const [field, value, key, want] of cases) {
    const g = guest();
    const out = await run(g, { [field]: value });
    assert.equal(out.ok, true, field);
    assert.deepEqual(doc(g)[key], want, `${field}=${value}`);
    assert.deepEqual(doc(g).tags, ["game", "tags"]);
    assert.equal(doc(g).auto_pause, true);
    assert.equal(g.st.created, 0);
    assert.equal(g.containers.get("factorio")!.running, true);
  }
});

test("visibility: turning public ON needs factorio.com credentials in the file; without them it is left alone and the customer is told", async () => {
  const g = guest();
  const out = await run(g, { visibility: true });
  assert.equal(out.ok, true);
  assert.deepEqual(doc(g).visibility, { public: true, lan: true }, "untouched (example had public true already; value not forced)");
  assert.match(out.notes.join(" "), /factorio\.com username and token/);
  const off = guest({ [FACTORIO_SETTINGS_PATH]: JSON.stringify({ visibility: { public: false, lan: true }, username: "", token: "" }) });
  await run(off, { visibility: true });
  assert.equal(doc(off).visibility.public, false, "not enabled without credentials");
  const withCreds = guest({ [FACTORIO_SETTINGS_PATH]: JSON.stringify({ visibility: { public: false, lan: true }, username: "nxeon", token: "tok123" }) });
  await run(withCreds, { visibility: true });
  assert.deepEqual(doc(withCreds).visibility, { public: true, lan: true });
  await run(withCreds, { visibility: false });
  assert.deepEqual(doc(withCreds).visibility, { public: false, lan: true }, "off is always written, lan kept");
  assert.equal(doc(withCreds).token, "tok123", "credentials never touched");
});

test("admins: the adminlist file is created / replaced whole from the field", async () => {
  const g = guest();
  const out = await run(g, { admins: "Alice, bob  Carol,alice" });
  assert.equal(out.ok, true);
  assert.deepEqual(JSON.parse(g.files.get(FACTORIO_ADMINLIST_PATH)!), ["Alice", "bob", "Carol"]);
  await run(g, { admins: "dave" });
  assert.deepEqual(JSON.parse(g.files.get(FACTORIO_ADMINLIST_PATH)!), ["dave"]);
  await run(g, { admins: "" });
  assert.deepEqual(JSON.parse(g.files.get(FACTORIO_ADMINLIST_PATH)!), []);
  assert.deepEqual(factorioAdminList(" a ,, b;c "), ["a", "b", "c"]);
});

test("idempotent: same values again write nothing and say so", async () => {
  const g = guest();
  await run(g, { max_players: 24, admins: "Alice" });
  const writes = g.log.filter((l) => l.startsWith("write")).length;
  const out = await run(g, { max_players: 24, admins: "Alice" });
  assert.equal(out.ok, true);
  assert.equal(g.log.filter((l) => l.startsWith("write")).length, writes);
  assert.match(out.notes.join(" "), /already matched/);
});

test("a write that does not verify is rolled back and reported as nothing changed", async () => {
  const g = guest({ [FACTORIO_SETTINGS_PATH]: EXAMPLE }, { corruptWrite: FACTORIO_SETTINGS_PATH });
  const out = await run(g, { max_players: 24 });
  assert.equal(out.ok, false);
  assert.equal(g.files.get(FACTORIO_SETTINGS_PATH), EXAMPLE);
  assert.match(out.notes.join(" "), /Nothing was changed/);
});

test("a settings file that is not JSON is left untouched", async () => {
  const g = guest({ [FACTORIO_SETTINGS_PATH]: "{ broken" });
  const out = await run(g, { max_players: 24 });
  assert.equal(out.ok, false);
  assert.equal(g.files.get(FACTORIO_SETTINGS_PATH), "{ broken");
});

test("a settings failure after the admin list was written puts the admin list back too", async () => {
  const g = guest({ [FACTORIO_SETTINGS_PATH]: "{ broken", [FACTORIO_ADMINLIST_PATH]: '["old"]\n' });
  const out = await run(g, { max_players: 24, admins: "new" });
  assert.equal(out.ok, false);
  assert.equal(g.files.get(FACTORIO_ADMINLIST_PATH), '["old"]\n');
});

test("no settings file yet (server never started): saved-only note, nothing written, admin list still handled", async () => {
  const g = guest({});
  const out = await run(g, { max_players: 24 });
  assert.equal(out.ok, true);
  assert.match(out.notes.join(" "), /hasn't created its settings file/);
  assert.equal(g.files.has(FACTORIO_SETTINGS_PATH), false);
});

test("the game password never appears in a note or a command line", async () => {
  const g = guest();
  const out = await run(g, { game_password: "Hunter2-Pw" });
  assert.ok(!JSON.stringify(out).includes("Hunter2-Pw"));
  assert.ok(!g.log.some((l) => l.includes("Hunter2-Pw") && !l.startsWith("write ")));
  assert.equal(doc(g).game_password, "Hunter2-Pw");
});

const SCRIPT = `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/factorio && chown 845:845 /opt/factorio && docker run -d --name factorio -e GENERATE_NEW_SAVE=true -e LOAD_LATEST_SAVE=true -e SAVE_NAME=nxeon -p 34197:34197/udp -p 27015:27015/tcp -v /opt/factorio:/factorio --restart unless-stopped factoriotools/factorio:stable`;

test("fresh install bakes the settings: the generated seed step really builds a patched file from the example (run with python3)", () => {
  const script = buildGameSetupScript({
    osTemplate: { setupScript: SCRIPT, family: "factorio" },
    gameConfig: { name: "My 'Factory'", description: "d", max_players: 24, game_password: "pw", visibility: true, allow_commands: "false", autosave_interval: 5, admins: "Alice, Bob" },
