  assert.deepEqual(GAME_CONFIG_SCHEMAS.barotrauma.fields.map((f) => f.key).sort(), Object.keys(BAROTRAUMA_SPEC.fields).sort());
});

test("the xml patcher edits case-insensitively, keeps everything else, escapes values, and only touches the root tag", () => {
  const out = patchXmlRootAttrs(SETTINGS, "serversettings", { name: 'A & "B" <c>', maxplayers: "12", ispublic: "True" });
  assert.equal(readXmlRootAttr(out, "serversettings", "name"), 'A & "B" <c>');
  assert.ok(out.includes('name="A &amp; &quot;B&quot; &lt;c&gt;"'));
  assert.ok(out.includes('MaxPlayers="12"') && out.includes('IsPublic="True"'), "original attribute casing kept");
  assert.ok(out.includes('PresetName="Normal"') && out.includes('TickRate="20"'), "other attributes and the nested element untouched");
  assert.equal(readXmlRootAttr(out, "serversettings", "PresetName"), undefined, "nested element's attributes are not root attributes");
