    const writeAt = g.log.findIndex((l) => l === `write ${BAROTRAUMA_SETTINGS_PATH}`);
    const startAt = g.log.findIndex((l) => l.startsWith("systemctl start"));
    assert.ok(stopAt >= 0 && stopAt < writeAt && writeAt < startAt, `stop < write < start (${stopAt},${writeAt},${startAt})`);
