  assert.equal(readXmlRootAttr(out, "serversettings", "PresetName"), undefined, "nested element's attributes are not root attributes");
  const added = patchXmlRootAttrs('<serversettings name="x">\n</serversettings>', "serversettings", { MaxPlayers: "5" });
  assert.equal(readXmlRootAttr(added, "serversettings", "MaxPlayers"), "5");
  assert.throws(() => patchXmlRootAttrs("<other/>", "serversettings", { a: "b" }));
});

test("each settings field is written into serversettings.xml with the game stopped, then the game is started again", async () => {
  const cases: [string, string | number | boolean, string, string][] = [
    ["SERVERNAME", "My Sub", "name", "My Sub"],
    ["PASSWORD", "pw-Sekrit9", "password", "pw-Sekrit9"],
    ["MAX_PLAYERS", 14, "MaxPlayers", "14"],
    ["PUBLICITY", true, "IsPublic", "True"],
  ];
  for (const [field, value, a, want] of cases) {
    const g = guest();
    const out = await run(g, { [field]: value });
    assert.equal(out.ok, true, field);
    assert.equal(attr(g, a), want, field);
    assert.equal(attr(g, "TickRate"), "20");
    assert.equal(g.containers.get("barotrauma")!.running, true, "started again");
    assert.equal(out.restarted, true);
    const stopAt = g.log.findIndex((l) => l.startsWith("systemctl stop"));
    const writeAt = g.log.findIndex((l) => l === `write ${BAROTRAUMA_SETTINGS_PATH}`);
    const startAt = g.log.findIndex((l) => l.startsWith("systemctl start"));
    assert.ok(stopAt >= 0 && stopAt < writeAt && writeAt < startAt, `stop < write < start (${stopAt},${writeAt},${startAt})`);
    assert.equal(g.st.created, 0, "settings never rebuild the container");
  }
});

