test("if the game does not come back up, the files are restored and it is started again", async () => {
  const g = guest();
  let starts = 0;
  const realExec = g.guest.exec.bind(g.guest);
  g.guest.exec = async (cmd, t) => {
    if (cmd.startsWith("systemctl start") && starts++ === 0) return { code: 1, stdout: "", stderr: "boom" };
    return realExec(cmd, t);
  };
  const out = await run(g, { SERVERNAME: "My Sub" });
  assert.equal(out.ok, false);
  assert.equal(attr(g, "name"), "Server", "previous file restored");
  assert.equal(g.containers.get("barotrauma")!.running, true, "previous settings started again");
});

test("if the game rewrites the file while starting and drops our value, we do not claim success", async () => {
  const g = guest();
