  g.guest.exec = async (cmd, t) => {
    const r = await realExec(cmd, t);
    if (cmd.startsWith("systemctl start")) g.files.set(BAROTRAUMA_SETTINGS_PATH, SETTINGS);
    return r;
  };
  const out = await run(g, { SERVERNAME: "My Sub" });
  assert.equal(out.ok, false);
  assert.match(out.notes.join(" "), /no longer matched for name/);
});

test("password: written verbatim, only 'set vs blank' is re-checked after the game may hash it; never in a note or command line", async () => {
