});

test("owner: a Client with all permissions is added for the SteamID; other clients are kept; re-saving changes nothing", async () => {
  const g = guest();
  const out = await run(g, { OWNER_STEAMNAME: "Captain", OWNER_STEAMID: "76561198012345678" }, ["OWNER_STEAMNAME", "OWNER_STEAMID"]);
  assert.equal(out.ok, true);
  const perms = g.files.get(BAROTRAUMA_PERMISSIONS_PATH)!;
  assert.ok(perms.includes('steamid="76561198000000001"') && perms.includes('name="Old Host"'), "existing client kept");
  assert.ok(/name="Captain"\s+steamid="76561198012345678"\s+permissions="All"/.test(perms));
  g.log.length = 0;
  const again = await run(g, { OWNER_STEAMNAME: "Captain", OWNER_STEAMID: "76561198012345678" }, ["OWNER_STEAMNAME"]);
  assert.equal(again.ok, true);
  assert.ok(!g.log.some((l) => l.startsWith("systemctl stop")));
  const renamed = await run(g, { OWNER_STEAMNAME: "Skipper", OWNER_STEAMID: "76561198012345678" }, ["OWNER_STEAMNAME"]);
