test("INSTALL_LUA is an env-recreate (the image reads it on every start), combined with a file edit in one stop/start", async () => {
  const g = guest();
  const out = await run(g, { INSTALL_LUA: true, SERVERNAME: "My Sub" }, ["INSTALL_LUA", "SERVERNAME"]);
